mapper.select:
SELECT fb.chat_feedback_no, fb.message_no, left(m.session_no::text, 8) AS session_key, s.scenario_no, sc.title AS scenario_title, fb.rating, fb.comment, fb.comment_ciphertext, fb.comment_key_id, fb.comment_encryption_version, fb.frst_reg_dt FROM tb_chat_feedback fb JOIN tb_chat_message m ON m.chat_message_no = fb.message_no JOIN tb_chat_session s ON s.chat_session_no = m.session_no JOIN tb_scenario sc ON sc.scenario_no = s.scenario_no
fb.rating = #{rating}
ORDER BY fb.frst_reg_dt DESC, fb.chat_feedback_no DESC LIMIT #{limit}

mapper.update:
UPDATE tb_chat_feedback
SET comment = #{comment},
    comment_ciphertext = #{commentCiphertext},
    comment_key_id = #{commentKeyId},
    comment_encryption_version = #{commentEncryptionVersion}
WHERE chat_feedback_no = #{id}
